// 论语二十篇的标题列表
const chapters = [
  '学而篇',
  '为政篇',
  '八佾篇',
  '里仁篇',
  '公冶长篇',
  '雍也篇',
  '述而篇',
  '泰伯篇',
  '子罕篇',
  '乡党篇',
  '先进篇',
  '颜渊篇',
  '子路篇',
  '宪问篇',
  '卫灵公篇',
  '季氏篇',
  '阳货篇',
  '微子篇',
  '子张篇',
  '尧曰篇'
];

// 获取当前日期，计算今天是今年的第几天
const today = new Date();
const dayOfYear = Math.floor((today - new Date(today.getFullYear(), 0, 0)) / 1000 / 60 / 60 / 24);
// 20篇论语，循环选择（0-19）
const chapterIndex = dayOfYear % 20;
const selectedChapter = chapters[chapterIndex];

// 获取网页内容
const htmlContent = $input.item.json.data || $input.item.json.body || '';

// 使用正则表达式提取对应篇章的内容
// 查找篇章标题和内容
const chapterRegex = new RegExp(`## 论语·${selectedChapter}注音版([\\s\\S]*?)(?=## 论语·|$)`, 'i');
const match = htmlContent.match(chapterRegex);

let chapterContent = '';
if (match && match[1]) {
  // 提取篇章内容，清理HTML标签
  chapterContent = match[1]
    .replace(/<[^>]+>/g, '') // 移除HTML标签
    .replace(/\\s+/g, ' ') // 合并多个空格
    .trim();

  // 如果内容太长，截取前2000字符
  if (chapterContent.length > 2000) {
    chapterContent = chapterContent.substring(0, 2000) + '...';
  }
} else {
  chapterContent = `未能找到${selectedChapter}的内容，请检查网页结构。`;
}

// 构建最终消息
const message = `📚 论语每日推送 - ${selectedChapter}\n\n${chapterContent}\n\n---\n来源：论语网 (http://www.lunyu8.cn/)`;

return {
  json: {
    chapterName: selectedChapter,
    chapterIndex: chapterIndex + 1,
    dayOfYear: dayOfYear,
    content: chapterContent,
    message: message,
    date: today.toISOString().split('T')[0]
  }
};
